package org.dromara.property.charge.binding.mysql;
import org.junit.jupiter.api.*; import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable; import java.sql.*; import java.time.LocalDate; import java.util.UUID; import static org.junit.jupiter.api.Assertions.*;
/** TASK-018B 房间收费设置有效期与事务行为的真实 MySQL 验收。 */
@EnabledIfEnvironmentVariable(named="ZBM_TEST_DB_URL",matches=".+") class ChargeBindingMySqlTest {
 private Connection connection; private long roomId;
 @BeforeEach void setUp() throws SQLException{connection=DriverManager.getConnection(System.getenv("ZBM_TEST_DB_URL"),System.getenv("ZBM_TEST_DB_USER"),System.getenv("ZBM_TEST_DB_PASSWORD"));assertEquals("zbm_property_test",connection.getCatalog(),"只允许在隔离测试库执行");roomId=id();}
 @AfterEach void cleanUp() throws SQLException{if(connection==null)return;try(PreparedStatement s=connection.prepareStatement("DELETE FROM pm_charge_binding WHERE object_id=?")){s.setLong(1,roomId);s.executeUpdate();}finally{connection.close();}}
 @Test void closedIntervalsOverlapAtBoundary() throws SQLException{insert(id(),11L,LocalDate.of(2026,1,1),LocalDate.of(2026,1,31));assertTrue(overlaps(11L,LocalDate.of(2026,1,31),LocalDate.of(2026,2,28)));assertFalse(overlaps(11L,LocalDate.of(2026,2,1),LocalDate.of(2026,2,28)));}
 @Test void nullEndBehavesAsInfinity() throws SQLException{insert(id(),11L,LocalDate.of(2026,3,1),null);assertTrue(overlaps(11L,LocalDate.of(2030,1,1),null));assertFalse(overlaps(11L,LocalDate.of(2026,1,1),LocalDate.of(2026,2,28)));}
 @Test void uniqueConflictRollsBackWholeTransaction() throws SQLException{insert(id(),11L,LocalDate.of(2026,1,1),null);connection.setAutoCommit(false);try{insert(id(),12L,LocalDate.of(2026,1,1),null);assertThrows(SQLException.class,()->insert(id(),11L,LocalDate.of(2026,2,1),null));connection.rollback();}finally{connection.setAutoCommit(true);}assertEquals(0,count(12L));assertEquals(1,count(11L));}
 private boolean overlaps(long itemId,LocalDate start,LocalDate end)throws SQLException{String sql="SELECT EXISTS(SELECT 1 FROM pm_charge_binding WHERE project_id=1 AND object_type='ROOM' AND object_id=? AND charge_item_id=? AND del_flag='0' AND (? IS NULL OR effective_start_date<=?) AND (effective_end_date IS NULL OR effective_end_date>=?))";try(PreparedStatement s=connection.prepareStatement(sql)){s.setLong(1,roomId);s.setLong(2,itemId);if(end==null){s.setNull(3,Types.DATE);s.setNull(4,Types.DATE);}else{s.setDate(3,Date.valueOf(end));s.setDate(4,Date.valueOf(end));}s.setDate(5,Date.valueOf(start));try(ResultSet r=s.executeQuery()){r.next();return r.getBoolean(1);}}}
 private void insert(long bindingId,long itemId,LocalDate start,LocalDate end)throws SQLException{try(PreparedStatement s=connection.prepareStatement("INSERT INTO pm_charge_binding(id,project_id,object_type,object_id,charge_item_id,charge_rule_id,effective_start_date,effective_end_date,status,sort,del_flag) VALUES(?,1,'ROOM',?,?,?,?,?,'0',0,'0')")){s.setLong(1,bindingId);s.setLong(2,roomId);s.setLong(3,itemId);s.setLong(4,itemId+100);s.setDate(5,Date.valueOf(start));if(end==null)s.setNull(6,Types.DATE);else s.setDate(6,Date.valueOf(end));s.executeUpdate();}}
 private int count(long itemId)throws SQLException{try(PreparedStatement s=connection.prepareStatement("SELECT COUNT(*) FROM pm_charge_binding WHERE object_id=? AND charge_item_id=?")){s.setLong(1,roomId);s.setLong(2,itemId);try(ResultSet r=s.executeQuery()){r.next();return r.getInt(1);}}}
 private static long id(){return Math.abs(UUID.randomUUID().getMostSignificantBits()>>>1);}
}
